import json,pathlib,os
r={'processes':[],'files':{}}
keys={'FREECAD_USER_HOME','SNAP_USER_COMMON','QT_QPA_PLATFORMTHEME','GTK_USE_PORTAL','DBUS_SESSION_BUS_ADDRESS','LD_LIBRARY_PATH','PYTHONPATH'}
for p in pathlib.Path('/proc').iterdir():
 if not p.name.isdigit():continue
 try:
  if (p/'comm').read_text().strip()=='FreeCAD':
   env={}
   for pair in (p/'environ').read_bytes().split(b'\0'):
    k,_,v=pair.partition(b'=')
    if k.decode(errors='replace') in keys:env[k.decode()]=v.decode(errors='replace')
   threads=[]
   for t in (p/'task').iterdir():
    try:
     stat=(t/'stat').read_text().split();threads.append({'tid':t.name,'comm':(t/'comm').read_text().strip(),'cpu_ticks':int(stat[13])+int(stat[14]),'wchan':(t/'wchan').read_text()})
    except FileNotFoundError:pass
   r['processes'].append({'pid':p.name,'env':env,'threads':threads})
 except (FileNotFoundError,PermissionError,ProcessLookupError):pass
root=pathlib.Path('/home/user/.actc_gui_ready_vm_001')
for name in ('entered.json','stdout.txt','gui_ready.json'):
 p=root/name
 if p.exists():r['files'][name]=p.read_text()[:3000]
print(json.dumps(r))
